'use strict';
// js/method.js and js/presets.js are generated by tools/make-presets.js; they must match their sources.
var assert = require('assert'), fs = require('fs'), path = require('path');
var root = path.join(__dirname, '..');
var tests = [];
tests.push({ name: 'js/method.js matches METHOD.md (run node tools/make-presets.js)', fn: function () {
  require('../js/method.js');
  assert.strictEqual(global.RSGAUGE.methodMd, fs.readFileSync(path.join(root, 'METHOD.md'), 'utf8'));
} });
tests.push({ name: 'js/presets.js matches samples/sample-project.json', fn: function () {
  require('../js/presets.js');
  assert.deepStrictEqual(global.RSGAUGE.presets.sample, JSON.parse(fs.readFileSync(path.join(root, 'samples/sample-project.json'), 'utf8')));
} });
tests.push({ name: 'Sample data is flagged fictional', fn: function () {
  var s = JSON.parse(fs.readFileSync(path.join(root, 'samples/sample-project.json'), 'utf8'));
  assert.strictEqual(s.fictional, true); assert.ok(/FICTIONAL/.test(s.notes));
} });
module.exports = tests;
